  let attr=parse_variant_attrs(&variant.attrs)?;let id=&variant.ident;let wire=variant_wire_name(&id.to_string(),&attr.rename,&attrs.rename_all);let carrier=format_ident!("{}{}NativeVariant",name,id);let slot=format_ident!("variant_{}",id.to_string().to_lowercase());let tag_type=format_ident!("{}{}NativeTag",name,id);let payload=format_ident!("{}{}NativePayload",name,id);let internal=attrs.tag.is_some()&&attrs.content.is_none();let external_unit=attrs.tag.is_none()&&matches!(variant.fields,Fields::Unit);let field_casing=attrs.field_rename_all(&attr);let casing=field_casing.as_ref().map(|value|quote!(rename_all=#value,));
