  let fields=match &variant.fields{
   Fields::Named(named)=>{let members=named.named.iter().map(|field|field.ident.as_ref().unwrap()).collect::<Vec<_>>();let typed=named.named.iter().map(|field|{let member=field.ident.as_ref().unwrap();let ty=&field.ty;let attributes=field.attrs.iter().filter(|attribute|attribute.path().is_ident("value"));quote!(#(#attributes)*#member:#ty)}).collect::<Vec<_>>();if internal{constructors.push(quote!(#name::#id{#(#members:value.#members,)*}));quote!(#(#typed,)*)}else{definitions.push(quote!(#[derive(#value::RetireOwned,#value::NativeReceive)]#[value(crate=#value_path,native_owned=#native_path,#casing)]#vis struct #payload{#(#typed,)*}));constructors.push(quote!(#name::#id{#(#members:value.payload.#members,)*}));quote!(payload:#payload)}},
   Fields::Unnamed(unnamed)=>{if internal&&unnamed.unnamed.len()!=1{return Err(syn::Error::new_spanned(variant,"internally tagged native variants require one declared record payload"));}let types=unnamed.unnamed.iter().map(|field|&field.ty).collect::<Vec<_>>();if types.len()==1{let ty=types[0];constructors.push(quote!(#name::#id(value.payload)));if internal{quote!(#[value(flatten)]payload:#ty)}else{quote!(payload:#ty)}}else{let indices=(0..types.len()).map(syn::Index::from).collect::<Vec<_>>();definitions.push(quote!(#[derive(#value::RetireOwned,#value::NativeReceive)]#[value(crate=#value_path,native_owned=#native_path)]#vis struct #payload(#(#types),*);));constructors.push(quote!(#name::#id(#(value.payload.#indices),*)));quote!(payload:#payload)}},
   Fields::Unit=>{constructors.push(quote!(#name::#id));quote!()},
  };
  let direct_type=match &variant.fields{
   Fields::Named(named)=>{let members=named.named.iter().map(|field|field.ident.as_ref().unwrap()).collect::<Vec<_>>();if internal{let typed=named.named.iter().map(|field|{let member=field.ident.as_ref().unwrap();let ty=&field.ty;let attributes=field.attrs.iter().filter(|attribute|attribute.path().is_ident("value"));quote!(#(#attributes)*#member:#ty)});definitions.push(quote!(#[derive(#value::RetireOwned,#value::NativeReceive)]#[value(crate=#value_path,native_owned=#native_path,#casing)]#vis struct #payload{#(#typed,)*}));}direct_constructors.push(quote!(#name::#id{#(#members:value.#members,)*}));quote!(#payload)},
   Fields::Unnamed(unnamed)=>{let types=unnamed.unnamed.iter().map(|field|&field.ty).collect::<Vec<_>>();if types.len()==1{let ty=types[0];direct_constructors.push(quote!(#name::#id(value)));quote!(#ty)}else{let indices=(0..types.len()).map(syn::Index::from).collect::<Vec<_>>();direct_constructors.push(quote!(#name::#id(#(value.#indices),*)));quote!(#payload)}},
   Fields::Unit=>{definitions.push(quote!(#[derive(#value::RetireOwned,#value::NativeReceive)]#[value(crate=#value_path,native_owned=#native_path)]#vis struct #payload{}));direct_constructors.push(quote!(#name::#id));quote!(#payload)},
  };direct_types.push(direct_type);direct_slots.push(format_ident!("direct_{}",id.to_string().to_lowercase()));
