  if !external_unit{definitions.push(quote!(#[derive(#value::RetireOwned,#value::NativeReceive)]#[value(crate=#value_path,native_owned=#native_path,#casing)]#vis struct #carrier{#body}));memberships.push(quote!(<#carrier as #native::native_decoding::owned::NativeRecordFields>::native_field_memberships(key)));key_bytes.push(quote!(<#carrier as #native::native_decoding::owned::NativeRecordFields>::native_field_key_bytes()));}else{memberships.push(quote!(0usize));key_bytes.push(quote!(0usize));}
